import{d as g,C as t,o as u,c,j as a,a as s,E as n,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"道德经第三十八章","description":"从上德不德到处厚居实，辨德、仁、义、礼的层次及执名强作的问题。","frontmatter":{"title":"道德经第三十八章","description":"从上德不德到处厚居实，辨德、仁、义、礼的层次及执名强作的问题。","category":"guide","aliases":["道德经第三十八章","老子第三十八章","dao de jing chapter 38"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-38.md","filePath":"daoism/dao-de-jing/chapter-38.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-38.md"},w=g({...m,setup(p){const i=[{id:"virtue-without-claiming-virtue",label:"上德不德，是以有德",showLabel:!0,sentences:[[{text:"上德",glossary:"shangde"},"不",{text:"德",glossary:"de-claim"},"，是以有德；",{text:"下德",glossary:"xiade"},"不失德，是以无德。"]],note:["【白话】上等的德不以德自居、不把德当作需要执持的名目，所以反而有德；下等的德刻意求持、不肯失掉有德之名，反而失去德的根本。","【王弼注择要】「德者，得也。」注说上德之人「唯道是用，不德其德」，又说「故虽有德而无德名也」，将有德与执持德名分开。","【读法】不德的德在本页作以德自居理解，不能直译成毫无道德；上下是在比较行事与用心的层次，不是给人划定不可改变的等级。"]},{id:"action-and-partial-purpose",label:"上德无为而无以为",showLabel:!0,sentences:[["上德",{text:"无为",glossary:"wuwei"},"而",{text:"无以为",glossary:"wuyiwei"},"；下德为之而",{text:"有以为",glossary:"youyiwei"},"。"]],note:["【白话】上德不妄加造作，也不以偏定的目的有所施为；下德则有意作为，并有所持定的目的与取向。两句同时比较怎样行动，以及为何而行动。","【王弼注择要】「无以为者，无所偏为也。」注说下德「求而得之，为而成之」，于是「立善以治物」，说明其有所建立、也有所局限。","【读法】无以为不是没有能力、没有效果，而是无所偏为；有以为也不能简单等同于日常一切有计划、有目标的工作。本章在辨以偏定名目行事的限度。"]},{id:"benevolence-and-righteousness",label:"上仁为之而无以为",showLabel:!0,sentences:[[{text:"上仁",glossary:"shangren"},"为之而无以为；",{text:"上义",glossary:"shangyi"},"为之而有以为。"]],note:["【白话】上等的仁有所施行，却无所偏私；上等的义有所施行，并有具体的判断与取向。二者虽都有行动，仁的普遍关爱与义的分别裁断仍有差别。","【王弼注择要】说上仁，注以「爱之无所偏私」解释；说上义，则举「忿枉祐直，助彼攻此」，指出它在具体是非间有所抑扬。","【读法】本页依王弼辨普遍施爱与分别裁断，不将仁义一概写成虚伪。义在具体处境中的必要性，也不因它有所取向便被取消。"]},{id:"ritual-demanding-a-response",label:"上礼为之而莫之应",showLabel:!0,sentences:[[{text:"上礼",glossary:"shangli"},"为之而莫之应，则",{text:"攘臂",glossary:"rangbi"},"而",{text:"扔",glossary:"reng"},"之。"]],note:["【白话】上等的礼有所施行，却没有人回应，于是捋起袖子、伸出手臂，强拉着别人跟从。礼由表达敬意滑向强求回应，问题就在这一转折中显露。","【王弼注择要】「尚好修敬，校责往来，则不对之间忿怒生焉。」注以计较来往是否相称、得不到回应便发怒，说明礼如何转为强制。","【读法】莫之应即没有人回应它。扔本页读 rēng，按牵引、强拉解释；辞书另收因、就等古义读法，不能直接用现代投掷义代入本句。"]},{id:"successive-loss-of-the-root",label:"故失道而后德",showLabel:!0,sentences:[["故失道而后德，失德而后仁，失仁而后义，失义而后",{text:"礼",glossary:"li"},"。"]],note:["【白话】所以，失掉道，才转而强调德；失掉德，才转而强调仁；失掉仁，才转而强调义；失掉义，才转而强调礼。越向外求形式上的补救，越须追问所依的根本是否已经失去。","【王弼注择要】「不能无为而贵博施，不能博施而贵正直，不能正直而贵饰敬。」王弼以无为、博施、正直、饰敬的递降说明这组失而后。","【读法】这里是本章对失本逐末的论述次序，不直接当作一份已经考证的历史年代次序。后文崇本以举其末，也说明仁义礼并非只有废弃一种归宿。"]},{id:"thin-trust-and-disorder",label:"夫礼者，忠信之薄而乱之首",showLabel:!0,sentences:[["夫礼者，",{text:"忠信",glossary:"zhongxin"},"之",{text:"薄",glossary:"bo"},"而乱之首。"]],note:["【白话】这里所批评的礼，是忠诚诚信已经衰薄之后的外在依凭，也可能成为争乱的开端。承接上段强求回应，礼若离开真实敬意，便容易反过来制造冲突。","【王弼注择要】「况务外饰而可久乎。」王弼把问题落在务求外在修饰而不能长久，并未仅凭举行仪式这一事实便判定一切礼都坏。","【读法】薄在这里是浅薄、衰薄，读 bó。乱之首连上文攘臂而扔之理解；不能由此推出诚实守信、相互尊重与必要的礼仪本身没有价值。"]},{id:"foreknowledge-and-outward-display",label:"前识者，道之华而愚之始",showLabel:!0,sentences:[[{text:"前识",glossary:"qianshi"},"者，道之",{text:"华",glossary:"hua"},"而愚之始。"]],note:["【白话】竞求先于别人知晓、以聪明预见自许，是道的外在浮华，也会成为愚昧的开端。这里警戒的是役使智力、舍本逐名，却自认掌握一切的取向。","【王弼注择要】「前识者，前人而识也。」注又说「竭其聪明以为前识，役其智力以营庶事」，却「愈丧笃实」，说明聪明何以反成失本之患。","【读法】前识的批评有本章和王注的具体条件，不泛指学习、调查或合理预判皆愚。华与下段实相对，取外在华饰义，读 huá。"]},{id:"abiding-in-substance",label:"处其厚，不居其薄",showLabel:!0,sentences:[["是以",{text:"大丈夫",glossary:"dazhangfu"},"处其厚，不居其薄；处其",{text:"实",glossary:"shi"},"，不居其华。"],["故去彼取此。"]],note:["【白话】因此，有担当的人安处于淳厚，不停留在浅薄；安处于真实笃实，不停留在外在浮华。所以舍去浅薄、浮华，取淳厚、笃实。","【王弼注择要】「守母以存其子，崇本以举其末。」注又说「仁德厚焉，行义正焉，礼敬清焉」，将归本理解为使仁义礼各得其正，而非只剩对它们的否定。","【读法】彼指薄与华，此指厚与实；须按前后指代来读。大丈夫是本章的理想人格称呼，其担当、笃实的提醒不限定为某一性别专有。"]}],r=[{id:"shangde",term:"上德",sense:1},{id:"de-claim",term:"德",sense:3},{id:"xiade",term:"下德",sense:1},{id:"wuwei",term:"无为",sense:1},{id:"wuyiwei",term:"无以为",sense:1},{id:"youyiwei",term:"有以为",sense:1},{id:"shangren",term:"上仁",sense:1},{id:"shangyi",term:"上义",sense:1},{id:"shangli",term:"上礼",sense:1},{id:"rangbi",term:"攘臂",sense:1},{id:"reng",term:"扔",sense:1},{id:"li",term:"礼",sense:1},{id:"zhongxin",term:"忠信",sense:1},{id:"bo",term:"薄",sense:1},{id:"qianshi",term:"前识",sense:1},{id:"hua",term:"华",sense:1},{id:"dazhangfu",term:"大丈夫",sense:1},{id:"shi",term:"实",sense:1}];return(x,e)=>{const o=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),c("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三十八章",tabindex:"-1"},[s("道德经第三十八章 "),a("a",{class:"header-anchor",href:"#道德经第三十八章","aria-label":'Permalink to "道德经第三十八章"'},"​")],-1)),n(o,{title:"为什么不自居有德，反而称为上德",summary:"《德经》由上德、下德起笔，逐层辨无为与有为、无所偏为与有所偏为，再写礼失其本而强求回应。后半追问德仁义礼怎样失去根本，并以处厚居实收束。",points:[{label:"先读",text:"不德不是没有德，而是不执德名、不以德自居；先辨语法与层次。"},{label:"再辨",text:"仁、义、礼的比较还涉及动机与回应，不能只用行动多少衡量。"},{label:"后看",text:"从忠信之薄与前识之华，回到王弼崇本举末的解释，理解取厚实的方向。"}],hint:"攘读 rǎng，攘臂是捋袖伸臂；扔本页读 rēng，取牵引、强拉义。前识的识读 shí。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:i,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"上德不德，是以有德；下德不失德，是以无德。",tone:"有德与执德名分开",guide:"先辨不德的动词用法，再看刻意维持德名为何可能失其根本。"},{text:"上礼为之而莫之应，则攘臂而扔之。",tone:"敬意怎样转成强求",guide:"当行礼变成必须得到相称回报，得不到回应就容易以强制替代敬意。"},{text:"是以大丈夫处其厚，不居其薄；处其实，不居其华。",tone:"归本以成全仁义礼",guide:"从忠信与笃实重建行事依据，循王弼崇本举末的读法理解去彼取此。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-本章比较的只是道德行为多少吗" tabindex="-1">象：本章比较的只是道德行为多少吗？ <a class="header-anchor" href="#象-本章比较的只是道德行为多少吗" aria-label="Permalink to &quot;象：本章比较的只是道德行为多少吗？&quot;">​</a></h3><p>比较不只在行为外观。上德与下德涉及是否执持德名；仁与义涉及有无偏私和分别取向；礼则进一步出现对回应的要求。因此同样一件善行，也须看用心、方式以及与根本的关系。</p><h3 id="理-批评仁义礼-为什么结尾仍说处厚居实" tabindex="-1">理：批评仁义礼，为什么结尾仍说处厚居实？ <a class="header-anchor" href="#理-批评仁义礼-为什么结尾仍说处厚居实" aria-label="Permalink to &quot;理：批评仁义礼，为什么结尾仍说处厚居实？&quot;">​</a></h3><p>问题在失道之后以外在名目替代根本，而不是只要有仁义礼就必定有错。王弼以守母、崇本解释归向厚实，并说仁德可厚、行义可正、礼敬可清，让末节重新有根可依。</p><h3 id="用-今天如何区分真实负责与表演德行" tabindex="-1">用：今天如何区分真实负责与表演德行？ <a class="header-anchor" href="#用-今天如何区分真实负责与表演德行" aria-label="Permalink to &quot;用：今天如何区分真实负责与表演德行？&quot;">​</a></h3><p>可以检视：行动是否帮助了具体的人，是否允许对方不按预期回应，以及在无人称赞时是否仍愿承担。不能仅凭善行得到公开表达，就断言当事人虚伪；判断仍需具体事实。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>不要让善意附带强制回报。</strong> 帮助或表达尊重之后，给对方不同回应的空间。若一无回应便愤怒，应重新辨认自己究竟在帮助，还是在索取服从与承认。</p><p><strong>让形式有实际内容。</strong> 检查一项仪式、评比或道德宣言，是否建立在真实的信任、照顾与责任上。若内容不足，先补实事，少用更密集的展示掩盖缺口。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我最想保住的一个好名声，是否影响了实际判断？如果没有赞许、没有相称回应，我仍愿意做哪一件负责的事？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本章正文与标点沿本站保留，与所据卷三 001a 经文相核；王注为本章集中长注，延至 004b，段内引文按所解释的关系择要列出，不伪作逐句紧随的原排版。</li><li>不德中的德另列以德自居、执持德名义；无以为依王弼无所偏为理解。仁、义、礼的层次比较与现代人格评判分开。</li><li>扔按汉典基本、详细解释所收牵引义读 rēng；辞书另有 réng、rěng、rèng 等古音义分列，本页说明所取，不据投掷的常用义误译。</li><li>前识循前人而识及役智失实的注解；末段循守母存子、崇本举末理解，不将批评外饰扩成废除一切仁义礼。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，001a–004b</a>。</p><p>字音字义参考：<a href="https://www.zdic.net/hans/%E6%89%94" target="_blank" rel="noreferrer">汉典「扔」牵引义及音义分列</a>。</p>',16))])}}});export{f as __pageData,w as default};
